import{_ as d,o as e,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"复数FIR 滤波器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.1.0-alpha/modules/complex_fir/index.md","filePath":"v0.1.0-alpha/modules/complex_fir/index.md"}'),r={name:"v0.1.0-alpha/modules/complex_fir/index.md"};function c(l,t,i,h,n,p){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="复数fir-滤波器" tabindex="-1">复数FIR 滤波器 <a class="header-anchor" href="#复数fir-滤波器" aria-label="Permalink to &quot;复数FIR 滤波器&quot;">​</a></h1><p>适用：v0.1.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>complex_fir</code> · 模块定义版本：6</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>对复数输入执行有限抽头卷积。实系数模式分别滤波 I/Q；复系数模式允许每个延迟项带有缩放和旋转，可构造简单复数回声和自定义频率响应。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>复数信号源.out → 复数 FIR 滤波器.in</code>。分别观察源、输出及输出频谱，用已知输入和少量抽头理解每个延迟项的贡献。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>抽头实部与虚部按相同位置配成复系数，两张列表必须等长。实系数模式中虚部都应为零；复系数的乘法会在 I/Q 之间产生耦合。</p><p>等采样率时，第一项作用于当前输入，后一项作用于更早的输入。改变抽取或插值后，按新的速率关系解释结果。标签延时声明只改变流标签位置，不改变信号或 Master 时间轴。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>系数类型<br><code>coefficient_type</code></td><td><code>real</code></td><td>实系数（ccf） (<code>real</code>)；复系数（ccc） (<code>complex</code>)</td><td>重新准备</td></tr><tr><td>抽头实部<br><code>taps_real</code></td><td><code>[1]</code></td><td>按字段类型填写，见下文说明</td><td>可在线应用</td></tr><tr><td>抽头虚部<br><code>taps_imag</code></td><td><code>[0]</code></td><td>按字段类型填写，见下文说明</td><td>可在线应用</td></tr><tr><td>抽取倍数<br><code>decimation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr><tr><td>插值倍数<br><code>interpolation</code></td><td><code>1</code></td><td>范围 1 至 1024；当前产品支持 1–1024，抽取和插值中最多一个大于 1；修改后须重新准备。</td><td>重新准备</td></tr><tr><td>原生标签延时声明<br><code>sample_delay</code></td><td><code>0</code></td><td>范围 0 至 2147483647；只改变 GNU 标签位置，不改变信号或 Master 时间轴；修改后重新准备。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>taps_real</code>、<code>taps_imag</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>抽头实部与虚部成组应用，在线加长受本次历史容量限制。系数类型、速率关系与标签延时声明变化后重新准备。快照中区分编辑值和实际回执。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><p>复数处理示例使用当前项加上前一项的半幅 <code>j</code> 倍，即 <code>y[n] = x[n] + 0.5j·x[n−1]</code>。观察输出的幅度和相位变化，并与只做整体旋转的复数增益器比较。示例没有进行速率变换。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>为什么虚部抽头影响实部输出？</strong> 复数乘法会交叉组合 I 与 Q，不能将两列抽头当作两个互不相关的实数滤波器。</p><p><strong>在线换长点表失败？</strong> 保留草稿，停止后重新准备，为新抽头建立足够的历史容量。</p>',28)])])}const b=d(r,[["render",c]]);export{m as __pageData,b as default};
